-- Israel: milestones + English translations. Generated in the same
-- shape as new_country_scaffold.py's output; INSERT OR IGNORE
-- throughout (idempotent). Israel's SHAAM allocation-number system is
-- a domestic-B2B-only clearance mandate, phased in via a shrinking
-- invoice threshold rather than taxpayer-size waves -- originally
-- legislated as a five-year rollout through 2028, accelerated via VAT
-- Implementation Order 01/2025 (Dec 2025) into a two-year rollout
-- ending June 2026. Sourced from the Israel Tax Authority's own
-- gov.il service pages, cross-checked against VATupdate's dedicated
-- Israel briefing (Jan 2026), Sovos, EDICOM, and vatit.com, which
-- independently agree on the threshold schedule and dates.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'il-law-enacted', id, '2023-05-31', 1, 'https://www.gov.il/en/service/request-assignment-number-for-tax-invoice', 0, '[]', NULL, 'none' FROM countries WHERE code = 'IL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-law-enacted', 'en', 'Economic Efficiency Law enacted, introducing the clearance system', 'Israel''s Economic Efficiency Law (Budget Amendments) for 2023-2024 amended the VAT Law 1975 to introduce a real-time invoice clearance system via temporary provisions, with the Ministry of Finance empowered to extend the regime. The law took effect 1 January 2024, though implementation was postponed due to the security situation at the time.', '["No action required yet -- this is the legal foundation the later mandatory phases build on", "Large VAT-registered businesses should begin monitoring Israel Tax Authority (ITA) guidance ahead of the pilot phase"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'il-pilot-25k', id, '2024-05-05', 0, 'https://www.gov.il/en/service/request-assignment-number-for-tax-invoice', 1, '[{"label": "Israel Tax Authority -- request an allocation number", "url": "https://www.gov.il/en/service/request-assignment-number-for-tax-invoice"}]', NULL, 'b2b' FROM countries WHERE code = 'IL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-pilot-25k', 'en', 'Pilot phase begins -- allocation numbers required above NIS 25,000', 'The SHAAM clearance platform went live for domestic B2B invoices exceeding NIS 25,000 (excluding VAT). This was a genuine pilot: every valid request received an allocation number automatically in 2024, with no rejections for content reasons, giving businesses a low-risk period to build out submission processes.', '["If you issue B2B invoices above NIS 25,000, start submitting via SHAAM -- either direct API integration or the ITA''s manual portal", "Map your invoice data to the required fields now, since scrutiny tightens from 2025"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'il-phase2-20k', id, '2025-01-01', 0, 'https://www.gov.il/en/service/request-assignment-number-for-tax-invoice', 1, '[{"label": "Israel Tax Authority -- request an allocation number", "url": "https://www.gov.il/en/service/request-assignment-number-for-tax-invoice"}]', NULL, 'b2b' FROM countries WHERE code = 'IL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase2-20k', 'en', 'Threshold drops to NIS 20,000 -- full enforcement powers activated', 'The mandatory threshold fell to NIS 20,000, and the pilot''s no-rejection grace ended: the ITA gained the ability to scrutinize submissions and refuse allocation numbers for invoices it deems irregular, with a formal review and hearing process available within 2 business days of a refusal.', '["Confirm every B2B invoice above NIS 20,000 carries a valid allocation number before relying on it for VAT deduction", "Review your submission data quality -- irregular-looking invoices can now genuinely be refused, not just flagged"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'il-phase3-10k', id, '2026-01-01', 0, 'https://www.vatupdate.com/2025/12/10/israel-accelerates-ctc-invoice-allocation-number-rollout-lower-thresholds-effective-2026/', 1, '[{"label": "Israel Tax Authority -- request an allocation number", "url": "https://www.gov.il/en/service/request-assignment-number-for-tax-invoice"}]', NULL, 'b2b' FROM countries WHERE code = 'IL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase3-10k', 'en', 'Accelerated threshold drop to NIS 10,000', 'The threshold fell to NIS 10,000, skipping the NIS 15,000 step originally planned -- part of a December 2025 acceleration (VAT Implementation Order 01/2025) that compressed what was legislated as a five-year rollout through 2028 into two years, ending mid-2026.', '["Re-check whether invoices you previously treated as below-threshold now require an allocation number", "If you haven''t yet integrated via API, the manual portal route becomes less practical as more of your invoice volume falls in scope"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'il-phase4-5k', id, '2026-06-01', 0, 'https://www.vatupdate.com/2026/06/20/israel-tightens-real-time-invoice-validation-with-lower-threshold-requirement/', 1, '[{"label": "Israel Tax Authority -- request an allocation number", "url": "https://www.gov.il/en/service/request-assignment-number-for-tax-invoice"}]', NULL, 'b2b' FROM countries WHERE code = 'IL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('il-phase4-5k', 'en', 'Final threshold reached -- NIS 5,000, the permanent floor', 'The threshold reached its final, permanent floor of NIS 5,000 (excluding VAT) -- no further reductions are currently scheduled. This completes the accelerated rollout roughly 18 months earlier than originally legislated, and brings the large majority of domestic B2B invoices into scope.', '["Confirm your systems handle allocation numbers for essentially all B2B invoices above NIS 5,000 -- this is now the baseline, not an edge case", "Remember B2C, B2G, and cross-border transactions remain outside this mandate''s scope"]');
